const IMBUE_BY_ID = new Map(IMBUEMENTS.map((x) => [x.id, x]));
export const getImbuement = (id: string): ImbueDef | undefined => IMBUE_BY_ID.get(id);
export const IMBUE_LEVELS = [1, 2, 3] as const;
export type ImbueLevel = (typeof IMBUE_LEVELS)[number];

/**
 * Imbuements for a slot; skill imbuements only for the vocation's skills. An item with a native skill or element
 * protection cannot take the imbuement of the same skill / element.
 */
export function imbuementsFor(slot: ImbueSlot, vocation: Vocation, item?: EquipmentItem): ImbueDef[] {
  const skills = VOCATION_SKILLS[vocation];
  const own = item?.bonus;
  return IMBUEMENTS.filter(
    (x) =>
      x.slots.includes(slot) &&
      (!x.skill || skills.includes(x.skill)) &&
      !(x.group === 'damage' && MAGE.has(vocation)) &&
      !(x.skill && own?.skills?.[x.skill]) &&
      !(x.group === 'protection' && x.element && own?.resist?.[x.element as keyof typeof own.resist]),
  );
}

const MAGE = new Set<Vocation>(['sorcerer', 'druid']);
const VOCATION_SKILLS: Record<Vocation, readonly ItemSkill[]> = {
  knight: ['sword', 'axe', 'club', 'magic', 'shielding'],
  paladin: ['distance', 'magic', 'shielding'],
  sorcerer: ['magic', 'shielding'],
  druid: ['magic', 'shielding'],
  monk: ['fist', 'magic', 'shielding'],
};

/**
 * D81: imbuements a weapon can take: none of an elemental damage kind when it deals elemental damage itself (a monk's
 * elemental bond does not count), none of a skill it already raises.
 */
export function weaponImbuements(
  w: { type?: string; element?: string; elementAttack?: unknown; specials?: { skills?: Partial<Record<string, number>> } },
  vocation: Vocation,
): ImbueDef[] {
  const elemental = !!w.elementAttack || (!!w.element && w.element !== 'physical' && w.type !== 'fist');
  return imbuementsFor('weapon', vocation).filter((x) => !(x.group === 'damage' && elemental) && !(x.skill && w.specials?.skills?.[x.skill]));
}

/** Imbuement slots of a weapon (unknown weapon: the usual maximum). */
export const WEAPON_IMBUE_SLOTS = 3;

// ---------------------------------------------------------------------------
// Exaltation Forge tiers (chance %, tiers 1..10; tiers 7–10 extrapolated from the second differences)

export type TierEffect = 'onslaught' | 'ruse' | 'momentum' | 'transcendence' | 'amplification';

export const TIER_EFFECT: Partial<Record<GearSlot | 'weapon', TierEffect>> = {
  weapon: 'onslaught',
  armor: 'ruse',
  helmet: 'momentum',
  legs: 'transcendence',
  boots: 'amplification',
};

export const TIER_CHANCE: Record<TierEffect, readonly number[]> = {
  onslaught: [0.5, 1.05, 1.7, 2.45, 3.3, 4.25, 5.3, 6.45, 7.7, 9.05],
  ruse: [0.5, 1.03, 1.62, 2.28, 3.0, 3.78, 4.62, 5.53, 6.5, 7.53],
  momentum: [2.0, 4.05, 6.2, 8.45, 10.8, 13.25, 15.8, 18.45, 21.2, 24.05],
  transcendence: [0.13, 0.27, 0.44, 0.64, 0.86, 1.11, 1.39, 1.7, 2.04, 2.41],
  amplification: [2.5, 5.4, 9.1, 13.6, 18.9, 25.0, 31.9, 39.6, 48.1, 57.4],
};

export const MAX_TIER = 10;

/** Highest tier of an item class (class 4: 10; lower classes: their number; no class: 0). */
export const maxTier = (cls: number | undefined): number => (!cls ? 0 : cls >= 4 ? MAX_TIER : cls);

export const tierChance = (effect: TierEffect, tier: number): number => (tier >= 1 ? TIER_CHANCE[effect][Math.min(MAX_TIER, tier) - 1] : 0);
